import{_ as a,o as s,c as i,a1 as n}from"./chunks/framework.CiMD_7j0.js";const h=JSON.parse('{"title":"Submission & AI Analysis","description":"","frontmatter":{"AIGC":{"ContentProducer":"001191110102MAD55U9H0F10002","ContentPropagator":"001191110102MAD55U9H0F10002","Label":"1","ProduceID":"7a619a27-5b27-42b5-a4f2-ac2f739ec1cf","PropagateID":"7a619a27-5b27-42b5-a4f2-ac2f739ec1cf","ReservedCode1":"206c41e9-54c6-4e6f-a770-8d4249398c4b","ReservedCode2":"206c41e9-54c6-4e6f-a770-8d4249398c4b"}},"headers":[],"relativePath":"en/marketplace/submission.md","filePath":"en/marketplace/submission.md","lastUpdated":null}'),t={name:"en/marketplace/submission.md"};function o(r,e,l,c,p,d){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="submission-ai-analysis" tabindex="-1">Submission &amp; AI Analysis <a class="header-anchor" href="#submission-ai-analysis" aria-label="Permalink to &quot;Submission &amp; AI Analysis&quot;">​</a></h1><h2 id="submission-data" tabindex="-1">Submission Data <a class="header-anchor" href="#submission-data" aria-label="Permalink to &quot;Submission Data&quot;">​</a></h2><p>Developers create a plugin draft in the website <a href="/apehub-web/profile.html">profile center</a>, filling in the plugin identifier, display name, description, category, tags, USDT pricing, logo, carousel images and demo info. Creating a plugin only produces a draft — it does not appear in the marketplace immediately.</p><h2 id="version-workbench" tabindex="-1">Version Workbench <a class="header-anchor" href="#version-workbench" aria-label="Permalink to &quot;Version Workbench&quot;">​</a></h2><p>Each plugin can maintain multiple versions. When uploading a ZIP, the platform validates the package structure, file sizes, <code>plugin.json</code> and the version number; only one current package is kept per version. Docs, changelogs and compatibility info belong to the version, not to the global plugin profile.</p><h2 id="ai-technical-docs" tabindex="-1">AI Technical Docs <a class="header-anchor" href="#ai-technical-docs" aria-label="Permalink to &quot;AI Technical Docs&quot;">​</a></h2><p>After the package is uploaded, static checks run first; then DeepSeek generates Markdown from the file tree and source summary. The generated output is only written to the current version draft, and the developer can edit it manually before submitting for review.</p><p>AI analysis is not an auto-approval gate: admins still need to review risk hints, source files, permission requirements and version docs.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Never put API keys, passwords, tokens, private keys, production database connection strings or personal data into a plugin package.</p></div><h2 id="submission-flow" tabindex="-1">Submission Flow <a class="header-anchor" href="#submission-flow" aria-label="Permalink to &quot;Submission Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create plugin → Create version → Upload package → Static check</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                    AI generates docs (retryable)</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                    Polish manually → Submit for review</span></span></code></pre></div><p>After review approval, an admin must still explicitly &quot;Publish&quot; the version to make it appear in the public marketplace.</p>`,12)])])}const m=a(t,[["render",o]]);export{h as __pageData,m as default};
